// ==UserScript==
// @name         UPC Halaxy branding (beta)
// @namespace    https://github.com/UrmstonPhysioClinic/upc-userscripts
// @version      2.9.1
// @homepageURL  https://github.com/UrmstonPhysioClinic/upc-userscripts
// @updateURL    https://raw.githubusercontent.com/UrmstonPhysioClinic/upc-userscripts/main/beta/branding.user.js
// @downloadURL  https://raw.githubusercontent.com/UrmstonPhysioClinic/upc-userscripts/main/beta/branding.user.js
// @description  Applies Urmston Physio Clinic's website branding (colours and logo) to the everyday Halaxy app.
// @author       Urmston Physio Clinic
// @match        https://eu.halaxy.com/*
// @exclude      https://eu.halaxy.com/book/*
// @exclude      https://eu.halaxy.com/patient*
// @run-at       document-start
// @grant        GM_registerMenuCommand
// @grant        GM_getValue
// @grant        GM_setValue
// ==/UserScript==

/*
 * How it works
 * ------------
 * Halaxy colours most of its app through one block of CSS variables per theme
 * (body.vs-theme.vs-theme-milky-way, -storm, -stardust and so on). This script
 * overrides those variables with !important, so the clinic colours apply
 * whichever Halaxy theme a user has picked. A second block covers the places
 * where Halaxy hard-codes its navy and bright blue instead of using a variable.
 *
 * Colours are taken from urmstonphysioclinic.com (style.css :root variables):
 *   --purple       #994DE6   buttons, accents (also the logo lettering)
 *   --purple-dark  #7A38C0   hover, links
 *   --purple-deep  #5C2899   headings
 *   --purple-pale  #F3EAFD   tints
 *   --purple-mid   #DCC5F9   highlights, text accents on dark
 *   --charcoal     #1E1E24   dark sections (used here for the side menu)
 *
 * Deliberately left alone: red/coral "danger" colours (delete, cancel, negative
 * balances, notification badges), so warnings still look like warnings.
 *
 * Font: Plus Jakarta Sans, as on the website, replaces Halaxy's text fonts.
 * Normal text renders at Medium weight minimum, so small text has solid strokes.
 * Tampermonkey menu: switch between the website font everywhere, for headings
 * only, or Halaxy's own font.
 *
 * Toggle on or off from the Tampermonkey menu: "Clinic branding: on/off".
 */

(function () {
  'use strict';

  // ---- Settings -------------------------------------------------------------

  const BRAND = {
    purple:     '#994DE6',
    purpleDark: '#7A38C0',
    purpleDeep: '#5C2899',
    purplePale: '#F3EAFD',
    purpleMid:  '#DCC5F9',
    charcoal:   '#1E1E24',
    greyLight:  '#E8E8EC',
    focusRing:  'rgba(153, 77, 230, .25)',
    text:       '#2D2D35',               // website body text (Halaxy uses #333)
    label:      '#585864',               // field labels: 7.0:1 on white, 6.2:1 on grey panel headers
    // Status pills: [text, background, border].
    // Pastel fills as strong as Halaxy's own, dark text: 6.59:1, 7.02:1, 7.51:1
    statusPositive: ['#14532D', '#B9E6C6', '#B9E6C6'],   // e.g. Paid in full (green)
    statusNegative: ['#7A1229', '#F7C3CE', '#F7C3CE'],   // e.g. Not yet paid, Draft, Discharged (rose)
    statusNeutral:  ['#4A1F7D', '#DCC5F9', '#DCC5F9'],   // e.g. Pending (clinic purple)
    danger:     '#B3261E',               // replaces Halaxy's coral #EC6B65, which fails contrast as text
    dangerDark: '#8C1D18',
  };

  /*
   * Accessibility (WCAG 2.2 AA), checked on Halaxy's default theme (Milky Way)
   * and on Storm:
   *   - #994DE6 is only used for fills, borders, bars and icons. As text it
   *     fails on Halaxy's light grey panels (4.06:1 on #F0F0F5, 3.54:1 on Storm).
   *   - Purple text on light backgrounds is #7A38C0 (5.1:1 or better) or
   *     #5C2899 (7.3:1 or better).
   *   - White text on #994DE6 is 4.61:1 (passes), on #7A38C0 6.66:1, on #5C2899 9.47:1.
   *   - Danger red #B3261E: 5.0:1 or better on every background, 6.54:1 under white text.
   *   - Panel headers keep Halaxy's light grey (#F0F0F5): charcoal titles 14.6:1, labels 6.17:1.
   *   - Contrast ratios assume solid strokes. At Halaxy's small sizes, thin
   *     strokes render lighter than their colour, so body text uses Medium
   *     weight as a minimum (see the font section).
   *   - Tabs: the selected tab is bold with a thick bright bar; hover is regular
   *     weight with a thin lavender bar, so the two never rely on colour alone.
   */

  const OPTIONS = {
    menuStyle:      'charcoal',           // 'charcoal' (like the website's dark sections) or 'purple' (deep purple)
    replaceLogo:    true,                 // clinic logo, in its white circle, at the top of the side menu
    logoHeight:     '6rem',               // Halaxy's own logo slot is 2.34rem
    replaceFavicon: true,                 // clinic icon in the browser tab
    panelAccent:    true,                 // thin purple bar on the left of panel headers, like the website's heading bar
    websiteFont:    'headings',           // default font mode: 'all' (Plus Jakarta Sans everywhere), 'headings'
                                          // (buttons, labels and headings only; Halaxy's font for body text) or
                                          // 'halaxy' (Halaxy's fonts). Switch from the Tampermonkey menu to compare.
    // Plus Jakarta Sans draws smaller than Halaxy's fonts at the same size, so it is scaled up:
    fontScaleLabels: '112%',              // in place of Ulm Grotesk (buttons, labels, headings). Measured: capitals were 8px vs 9px
    fontScaleBody:   '112%',              // in place of Beatrice (body text). Raise or lower to taste
  };

  // Same favicon the booking page uses (set in Halaxy's white-label settings).
  const FAVICON_URL = 'https://eu.halaxy.com/a/file/get/public/6184b00f06ed53264c96f9b48ac54784ee13bd40.png';

  // Clinic logo (white circle, transparent corners), as on the website and booking page.
  const LOGO_DATA_URI = 'data:image/png;base64,';

  // ---- Styles ---------------------------------------------------------------

  const B = BRAND;
  const MENU_BG = OPTIONS.menuStyle === 'purple' ? B.purpleDeep : B.charcoal;
  const MENU_BAR = OPTIONS.menuStyle === 'purple' ? B.purpleMid : B.purple;
  // "html body" prefix: beats Halaxy's own selectors (including its !important
  // rules) regardless of the order the stylesheets load in.
  const S = 'html body';
  // Stronger prefix for the few places Halaxy uses theme-specific !important
  // rules (specificity 0,4,1). Repeating .vs-theme counts twice: this is 0,4,2+.
  const ST = 'html body.vs-theme.vs-theme[class]';

  function helpIcon(fill) {
    const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'>`
      + `<circle cx='12' cy='12' r='12' fill='${fill}'/>`
      + `<text x='12' y='17' text-anchor='middle' font-family='Arial,sans-serif' font-weight='700' font-size='15' fill='#fff'>?</text></svg>`;
    return 'data:image/svg+xml,' + encodeURIComponent(svg);
  }

  const css = `
/* 1. Halaxy theme variables ------------------------------------------------ */
${S} {
  --vs-theme-primary: ${B.purpleDark} !important;
  --primary-color: ${B.purpleDark} !important;

  /* Buttons */
  --vs-btn-primary-active-color: ${B.purpleDeep} !important;
  --vs-btn-outline-primary-hover-bg-color: ${B.purple} !important;
  --vs-btn-outline-primary-hover-color: #fff !important;
  --vs-btn-outline-primary-hover-default-hover-bg-color: ${B.purple} !important;
  --vs-btn-outline-primary-light-active-bg-color: ${B.purple} !important;
  --vs-btn-outline-primary-light-active-border-color: ${B.purpleDark} !important;
  --vs-btn-outline-primary-light-active-hover-bg-color: ${B.purpleDark} !important;
  --vs-btn-outline-primary-light-border-color: ${B.purpleDark} !important;
  --vs-btn-outline-primary-light-color: ${B.purpleDeep} !important;
  --vs-btn-outline-primary-light-hover-bg-color: ${B.purpleDark} !important;
  --vs-btn-outline-primary-light-hover-border-color: ${B.purpleDark} !important;
  --vs-btn-outline-primary-light-active-color: #fff !important;
  --vs-btn-outline-primary-light-hover-color: #fff !important;

  /* Side menu */
  --vs-mainmenu-bg-color: ${MENU_BG} !important;
  --vs-mainmenu-color: #fff !important;
  --vs-mainmenu-item-hover-color: ${B.purpleMid} !important;
  --vs-mainmenu-item-active-color: #fff !important;
  --vs-mainmenu-scrollbar-thumb-bg-color: ${B.purple} !important;
  ${OPTIONS.replaceLogo ? `--vs-theme-logoWrapper-bg-image: url("${LOGO_DATA_URI}") !important;` : ''}

  /* Top bar: white, like the website's navigation */
  --vs-header-bg-color: #fff !important;

  /* Headings and links */
  /* Headings in charcoal, like the website; purple is kept for buttons, links, tabs and highlights */
  --vs-heading-color: ${B.charcoal} !important;
  --vs-heading-h3-color: ${B.charcoal} !important;
  --vs-link-a-color: ${B.purpleDark} !important;
  --vs-link-a-hover-color: ${B.purpleDeep} !important;
  --vs-icon-hover-color: ${B.purple} !important;

  /* Calendar */
  --vs-cal-appt-header-color: ${B.purpleDeep} !important;
  --vs-cal-appt-card-header-hover-color: ${B.purpleDark} !important;
  --vs-cal-appt-card-header-active-color: ${B.purpleDeep} !important;
  --vs-cal-appt-card-btn-close-bg-color: ${B.purpleMid} !important;
  --vs-cal-colHead-color: ${B.purpleDeep} !important;
  --vs-cal-colHead-today-bg-color: ${B.purpleMid} !important;
  --vs-cal-colHead-today-color: ${B.purpleDeep} !important;
  --vs-cal-month-timeslot-dateLabel-hasEvent-color: ${B.purpleDark} !important;
  --vs-cal-timeline-bg-color: ${B.purple} !important;
  --vs-cal-timeslot-hover-bg-color: ${B.purplePale} !important;
  --vs-cal-timeslot-selected-hover-bg-color: ${B.purple} !important;

  /* Date pickers */
  --vs-flatpickr-header-bg-color: ${B.purpleDark} !important;
  --vs-flatpickr-month-nav-hover-fill: ${B.purpleMid} !important;
  --vs-flatpickr-today-border-color: ${B.purple} !important;

  /* Forms and lookups */
  --vs-form-chosen-li-highlighted-bg-color: ${B.purpleDark} !important;
  --vs-form-control-box-shadow-color: ${B.focusRing} !important;
  --vs-form-custom-control-input-bg-color: ${B.purple} !important;
  --vs-me-li-hover-bg-color: ${B.purpleDark} !important;
  --vs-me-li-hover-color: #fff !important;
  --vs-me-li-add-new-dd-background: ${B.purpleMid} !important;
  --vs-me-li-add-new-dd-color: #212529 !important;
  --vs-me-result-wrapper-border-color: ${B.purple} !important;

  /* Text, closer to the website (panels keep Halaxy's light grey) */
  --vs-theme-body-color: ${B.text} !important;
  --vs-heading-h1-color: ${B.charcoal} !important;
  --vs-viewData-label-color: ${B.label} !important;
  --vs-search-searchData-th-color: ${B.label} !important;
  --vs-form-input-placeholder-color: ${B.label} !important;
  --vs-status-badge-neutral-bg-color: ${B.statusNeutral[1]} !important;
  --vs-status-badge-neutral-border-color: ${B.statusNeutral[2]} !important;

  /* Tabs, lists, popovers, modals */
  --vs-nav-tabs-nav-link-active-color: ${B.purpleDeep} !important;
  --vs-nav-tabs-nav-link-active-bottom-border-color: ${B.purple} !important;
  --vs-nav-tabs-nav-link-hover-color: ${B.purpleDark} !important;
  --vs-nav-tabs-nav-link-hover-bottom-border-color: ${B.purpleMid} !important;
  --vs-list-pagination-btn-active-bg-color: ${B.purpleDeep} !important;
  --vs-list-pagination-btn-hover-bg-color: ${B.purpleMid} !important;
  --vs-popover-light-header-bg-color: ${B.purplePale} !important;
  --vs-popover-light-header-color: ${B.purpleDeep} !important;
  --vs-modal-success-icon-color: ${B.purpleDeep} !important;
  --vs-modal-error-a-color: ${B.purpleMid} !important;
  --vs-primary-th-background: ${B.purpleDeep} !important;
  --vs-creditWidget-color: ${B.purpleDark} !important;
  --vs-balance-positive-color: ${B.purpleDeep} !important;

  /* Halaxy's own white-label variables, for any component that reads them */
  --vs-white-label-primary-color: ${B.purpleDeep} !important;
  --vs-white-label-secondary-color: ${B.purpleDark} !important;
  --vs-white-label-primary-hover-color: ${B.purpleDark} !important;
  --vs-white-label-secondary-hover-color: ${B.purpleDeep} !important;
  --vs-white-label-header-text-color: #fff !important;
  --vs-white-label-header-hover-color: #333 !important;
  --vs-white-label-bg-color: ${B.purplePale} !important;
  --vs-white-label-btn-primary-text-color: #fff !important;
  --vs-white-label-btn-secondary-text-color: #fff !important;
  --vs-white-label-menu-hover-color: ${B.purplePale} !important;
  --vs-white-label-menu-active-color: ${B.purpleMid} !important;

  /* Danger / warning: still red, but dark enough to read */
  --vs-btn-outline-danger-border-color: ${B.danger} !important;
  --vs-btn-outline-danger-color: ${B.danger} !important;
  --vs-btn-outline-danger-hover-bg-color: ${B.danger} !important;
  --vs-btn-outline-danger-hover-color: #fff !important;
  --vs-btn-filled-danger-hover-bg-color: ${B.dangerDark} !important;
  --vs-balance-negative-color: ${B.danger} !important;
  --vs-notification-badge-bg-color: ${B.danger} !important;

  /* Help button: Halaxy's is white on light blue (1.6:1). Purple circle, white "?" */
  --vs-context-help-btn-bg: url("${helpIcon(B.purpleDark)}") no-repeat !important;
  --vs-context-help-btn-hover-bg: url("${helpIcon(B.purpleDeep)}") no-repeat !important;
}

/* 2. Places Halaxy hard-codes its blues ------------------------------------- */

/* Primary buttons: purple, darker on hover (as on the website) */
${S} .btn-primary,
${S} .btn-primary:focus,
${S} .btn-primary:not(:disabled):not(.disabled):active,
${S} .btn-primary:not(:disabled):not(.disabled).active {
  background-color: ${B.purple} !important;
  border-color: ${B.purple} !important;
  color: #fff !important;
}
${S} .btn-primary:hover {
  background-color: ${B.purpleDark} !important;
  border-color: ${B.purpleDark} !important;
}
${S} .btn-primary:focus,
${S} .btn-outline-primary:focus {
  box-shadow: 0 0 0 .2rem ${B.focusRing} !important;
}

/* Outline buttons: purple outline and deep purple text, fills purple on hover
   (as on the website). 1px: a 2px outline looked too heavy where the
   calendar's buttons sit side by side. */
${S} .btn-outline-primary,
${S} .btn-outline-primary i,
${S} .btn-outline-primary-light:not(.upc-filled),
${S} .btn-outline-primary-light:not(.upc-filled) i {
  color: ${B.purpleDeep} !important;
  border-color: ${B.purple} !important;
}
${S} .btn-outline-primary:hover:not(:disabled):not(.disabled),
${S} .btn-outline-primary:hover:not(:disabled):not(.disabled) i {
  background-color: ${B.purple} !important;
  border-color: ${B.purple} !important;
  color: #fff !important;
}
${S} .btn-outline-primary:hover:not(:disabled):not(.disabled) i { background-color: transparent !important; }
${S} .btn-primary-neg:hover { background-color: ${B.purple} !important; }
${S} .btn-secondary-neg:hover { background-color: ${B.purpleMid} !important; color: ${B.purpleDeep} !important; }
${S} .btn-outline-white:hover { color: ${B.purpleDeep} !important; }

/* Halaxy's hard-coded coral */
${S} .btn-danger:hover { color: ${B.danger} !important; }
${S} .text-helio-beam { color: ${B.danger} !important; }

/* Tabs: selected = bold + thick bright bar; hover = thin lavender bar */
${S} .nav-tabs .nav-link.active,
${S} .nav-tabs .nav-item.show .nav-link {
  font-weight: 700 !important;
  color: ${B.purpleDeep} !important;
  box-shadow: inset 0 -2px 0 ${B.purple};
}
${S} .nav-tabs .nav-link:not(.active):hover { font-weight: inherit; color: ${B.purpleDark} !important; }

/* Status pills (invoice status, patient status): rounded, tinted and
   semibold like the website's tags. Halaxy's were thin capitals on pink,
   light blue and grey. Halaxy's markup: span.status-badge.positive|negative|neutral */
${S} .status-badge {
  border: 1px solid transparent !important;
  border-radius: 999px !important;
  padding: .12rem .6rem !important;
  font-weight: 600 !important;
  letter-spacing: .04em !important;
  line-height: 1.5 !important;
}
${S} .status-badge.status-badge-small { font-size: .72rem !important; }
${S} .status-badge.positive { color: ${B.statusPositive[0]} !important; background: ${B.statusPositive[1]} !important; border-color: ${B.statusPositive[2]} !important; }
${S} .status-badge.negative { color: ${B.statusNegative[0]} !important; background: ${B.statusNegative[1]} !important; border-color: ${B.statusNegative[2]} !important; }
${S} .status-badge.neutral  { color: ${B.statusNeutral[0]} !important;  background: ${B.statusNeutral[1]} !important;  border-color: ${B.statusNeutral[2]} !important; }

${OPTIONS.panelAccent ? `/* Panel headers: thin purple bar on the left (grey background kept) */
${S} .card > .card-header { box-shadow: inset 4px 0 0 ${B.purple}; }
` : ''}
/* Bootstrap's own grey text */
${S} .text-muted { color: ${B.label} !important; }

/* Bootstrap utility colours. Halaxy repeats some of these per theme with
   !important (body.vs-theme.vs-theme-milky-way .text-primary etc.), so these
   use a stronger prefix to win on every theme. */
${ST} .bg-primary { background-color: ${B.purpleDark} !important; }
${ST} a.bg-primary:hover,
${ST} a.bg-primary:focus,
${ST} button.bg-primary:hover,
${ST} button.bg-primary:focus { background-color: ${B.purpleDeep} !important; }
${ST} h1.text-primary,
${ST} h2.text-primary,
${ST} h3.text-primary,
${ST} h4.text-primary { color: ${B.charcoal} !important; }
${ST} .text-primary,
${S} .blue-icon,
${S} .text-midnight-dusk { color: ${B.purpleDeep} !important; }
${S} .text-blue-ribbon { color: ${B.purpleDark} !important; }
${ST} .border-primary,
${S} .border-blue-ribbon { border-color: ${B.purple} !important; }
${S} .badge-primary { background-color: ${B.purpleDark} !important; }
${S} .progress-bar { background-color: ${B.purple}; }

/* Tabs, pills, pagination, dropdowns, list groups */
${S} .active > a { border-bottom-color: ${B.purple}; }
${S} .modal .nav-tabs .nav-link { color: ${B.purpleDeep}; }
${S} .modal .nav-tabs .nav-link.active,
${S} .modal .nav-tabs .nav-link:focus { border-color: ${B.purple}; }
${S} .nav-pills .nav-link.active,
${S} .nav-pills .show > .nav-link { background-color: ${B.purpleDark}; }
${S} .page-item.active .page-link { background-color: ${B.purpleDeep}; border-color: ${B.purpleDeep}; }
${S} .page-link { color: ${B.purpleDark}; }
${S} .dropdown-item.active,
${S} .dropdown-item:active,
${S} .list-group-item.active { background-color: ${B.purpleDark}; border-color: ${B.purpleDark}; color: #fff; }
${S} .dropdown-item:hover { background-color: ${B.purplePale}; }
${S} .results-container .list-group-item-action:hover { color: ${B.purpleDark} !important; }

/* Form focus and checkboxes */
${S} .form-control:focus,
${S} .custom-select:focus {
  border-color: ${B.purple};
  box-shadow: 0 0 0 .2rem ${B.focusRing};
}
${S} .custom-control-input:checked ~ .custom-control-label::before {
  background-color: ${B.purple};
  border-color: ${B.purple};
}
${S} .custom-control-input:focus ~ .custom-control-label::before {
  box-shadow: 0 0 0 .2rem ${B.focusRing};
}

/* Icon hover (but not icons sitting inside buttons, which keep the button's colour) */
${S} #headerIcons i:hover,
${S} #toolbar-icons i:hover,
${S} [class^="icon-"]:hover,
${S} [class*=" icon-"]:hover { color: ${B.purple}; }
${S} .btn [class^="icon-"]:hover,
${S} .btn [class*=" icon-"]:hover,
${S} .btn:hover [class^="icon-"],
${S} .btn:hover [class*=" icon-"] { color: inherit; }

/* PrimeNG widgets (dropdowns, date pickers, checkboxes, switches) */
${S} .p-dropdown-panel .p-dropdown-items .p-dropdown-item.p-highlight,
${S} .p-multiselect-panel .p-multiselect-items .p-multiselect-item.p-highlight,
${S} .p-autocomplete-panel .p-autocomplete-items .p-autocomplete-item.p-highlight,
${S} .p-datepicker table td > span.p-highlight,
${S} .p-datepicker .p-monthpicker .p-monthpicker-month.p-highlight,
${S} .p-datepicker .p-yearpicker .p-yearpicker-year.p-highlight {
  background: ${B.purpleDark};
  color: #fff;
}
${S} .p-checkbox .p-checkbox-box.p-highlight,
${S} .p-input-filled .p-checkbox .p-checkbox-box.p-highlight {
  background: ${B.purple};
  border-color: ${B.purple};
}
${S} .p-checkbox:not(.p-checkbox-disabled) .p-checkbox-box.p-highlight:hover {
  background: ${B.purpleDark};
  border-color: ${B.purpleDark};
}
${S} .p-checkbox:not(.p-checkbox-disabled) .p-checkbox-box.p-focus { border-color: ${B.purple}; }
${S} .p-inputswitch.p-inputswitch-checked .p-inputswitch-slider,
${S} .p-inputswitch.p-inputswitch-checked:not(.p-disabled):hover .p-inputswitch-slider { background: ${B.purple}; }

/* Halaxy reuses the menu colour for these; keep them purple even with a charcoal menu */
${S} .cal .timeslot.ts-sel { background-color: ${B.purple} !important; }
${S} #message-list .chat .messages.mine .message .content,
${S} .message-list .chat .messages.mine .message .content { background: ${B.purpleDark}; }
${S} #message-list .chat .messages.mine .message .content:after,
${S} .message-list .chat .messages.mine .message .content:after { border-left-color: ${B.purpleDark}; }

/* Text and icons inside a solid purple button are white (the script marks
   these buttons with .upc-filled). Fixes the calendar's prev/next chevrons on
   the selected Day/Week/Month button. Halaxy's button icons are an icon font,
   so colour is all that's needed. Borders are left alone: Bootstrap draws
   dropdown arrows from borders with transparent sides, and those take the
   white text colour automatically. */
${S} .upc-filled,
${S} .upc-filled * { color: #fff !important; }
${S} .upc-filled svg [stroke]:not([stroke="none"]) { stroke: #fff !important; }

/* 3. Top bar and side menu --------------------------------------------------- */

/* Thin line under the white top bar, like the website's navigation */
${S} #headerWrapper { box-shadow: 0 1px 0 rgba(0, 0, 0, .08); }

/* Active item: white, bold, with a bar on the left */
${S} #mainMenu > ul > li.mainmenu-item.active > a,
${S} #mainMenu > ul > li.mainmenu-item > ul > li.mainmenu-item.active a { font-weight: 600; }
${S} #mainMenu > ul > li.mainmenu-item.active { box-shadow: inset 4px 0 0 ${MENU_BAR}; }
${S} #mainMenu .mainmenu-inner { scrollbar-color: ${B.purple} ${MENU_BG}; }

${OPTIONS.replaceLogo ? `
/* Logo in its white circle, scaled to fit rather than cropped */
${S} #logoWrapper {
  background-image: url("${LOGO_DATA_URI}") !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  height: ${OPTIONS.logoHeight} !important;
  margin-top: .75rem;
  margin-bottom: .75rem;
}
${S} .mainmenu-collapsed #logoWrapper { height: 2.34rem !important; }
` : ''}


`;

  // ---- Apply ----------------------------------------------------------------

  const enabled = GM_getValue('enabled', true);

  GM_registerMenuCommand(`Clinic branding: ${enabled ? 'on (click to turn off)' : 'off (click to turn on)'}`, () => {
    GM_setValue('enabled', !enabled);
    location.reload();
  });

  const FONT_MODES = { all: 'website font everywhere', headings: 'website font for headings only', halaxy: "Halaxy's own font" };
  const fontMode = FONT_MODES[GM_getValue('fontMode')] ? GM_getValue('fontMode') : OPTIONS.websiteFont;
  if (enabled) {
    Object.entries(FONT_MODES).forEach(([mode, label]) => {
      GM_registerMenuCommand(`${mode === fontMode ? '\u2713 ' : '   '}Font: ${label}`, () => {
        GM_setValue('fontMode', mode);
        location.reload();
      });
    });
  }

  if (!enabled) return;

  const style = document.createElement('style');
  style.id = 'upc-branding';
  style.textContent = css;

  // Inject immediately so there's no flash of Halaxy blue, then move to the end
  // of <head> once it exists.
  (document.head || document.documentElement).appendChild(style);

  if (fontMode !== 'halaxy') registerWebsiteFont(fontMode);

  document.addEventListener('DOMContentLoaded', () => {
    document.head.appendChild(style);
    if (OPTIONS.replaceFavicon) watchFavicon();
    watchPage();
  });

  // ---- Page fixes that need JavaScript ------------------------------------------
  //
  // 1. Solid purple buttons: marked with .upc-filled so their contents can be
  //    forced white. Halaxy draws some icons inside buttons in the border
  //    colour, which vanishes once the button is filled.
  // 2. Patient alert notices (e.g. "Package ends ..."): Halaxy writes the alert
  //    colour inline, e.g. #AB68FF, which is 3.1:1 on its pale background. Each
  //    alert colour is darkened just enough to reach 4.5:1, keeping its hue.

  const toRgb = (hex) => {
    const n = parseInt(hex.slice(1), 16);
    return `rgb(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255})`;
  };
  const parseRgb = (s) => (s.match(/[\d.]+/g) || []).map(Number);
  const luminance = ([r, g, b]) => {
    const f = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
  };
  const contrast = (a, b) => {
    const [x, y] = [luminance(a), luminance(b)].sort((m, n) => n - m);
    return (x + 0.05) / (y + 0.05);
  };

  function fixAlertColours() {
    document.querySelectorAll('.alert-background-container, .alert-background-container [style*="color"]').forEach((el) => {
      if (!el.style.color) return;
      const current = el.style.color;
      if (el.dataset.upcColour === current) return;      // already adjusted
      const container = el.closest('.alert-background-container') || el;
      const bgParts = parseRgb(getComputedStyle(container).backgroundColor);
      const alpha = bgParts.length === 4 ? bgParts[3] : 1;
      const bg = bgParts.slice(0, 3).map((c) => c * alpha + 255 * (1 - alpha)); // over white
      let rgb = parseRgb(current).slice(0, 3);
      for (let i = 0; i < 20 && contrast(rgb, bg) < 4.5; i++) rgb = rgb.map((c) => c * 0.92);
      const fixed = `rgb(${rgb.map(Math.round).join(', ')})`;
      el.style.setProperty('color', fixed, 'important');
      el.dataset.upcColour = el.style.color;
    });
  }

  function watchPage() {
    const fills = new Set([B.purple, B.purpleDark, B.purpleDeep].map(toRgb));
    const scan = () => {
      document.querySelectorAll('button, [class*="btn"]').forEach((el) => {
        if (el.matches(':hover')) return;          // hover fills are temporary; leave as is
        el.classList.toggle('upc-filled', fills.has(getComputedStyle(el).backgroundColor));
      });
      fixAlertColours();
    };
    let queued = false;
    const queue = () => {
      if (queued) return;
      queued = true;
      requestAnimationFrame(() => { queued = false; scan(); });
    };
    scan();
    new MutationObserver(queue).observe(document.body, {
      childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'],
    });
  }

  // ---- Website font ---------------------------------------------------------
  //
  // Halaxy's text uses two fonts, "Beatrice" (body) and "Ulm Grotesk" (buttons,
  // labels, headings). Rather than restyling elements, this registers Plus
  // Jakarta Sans under those two names, for every weight and style Halaxy
  // declares. Fonts added this way take precedence over Halaxy's own
  // @font-face rules, every piece of Halaxy text picks them up, and Halaxy's
  // icon fonts (halaxy, primeicons, calendar-icons) are untouched.
  //
  // The font is built in, not downloaded, so Halaxy's security settings can't
  // block it. Plus Jakarta Sans is (c) The Plus Jakarta Sans Project Authors,
  // SIL Open Font License 1.1 (free to embed).

  function registerWebsiteFont(mode) {
    if (!document.fonts || typeof FontFace === 'undefined') return;
    const data = fontData();
    const toBuffer = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0)).buffer;
    const buffers = {};
    for (const [key, b64] of Object.entries(data.files)) buffers[key] = toBuffer(b64);

    const body = OPTIONS.fontScaleBody, labels = OPTIONS.fontScaleLabels;
    const bodyFaces = mode === 'all' ? [
      // Halaxy's Beatrice stops at 600, so bold (700) fell back to semibold. 700 and 800 added.
      ...[300, 400, 500, 600, 700, 800].flatMap((w) => [['Beatrice', w, 'normal', body], ['Beatrice', w, 'italic', body]]),
      ['Beatrice Light', 300, 'normal', body],
    ] : [];
    const faces = [
      // [family name Halaxy uses, weight, style, scale]
      ...bodyFaces,
      ['Ulm Grotesk', 700, 'normal', labels],
      ['Ulm Grotesk', 800, 'normal', labels],
      // Also under its own name, for anything that asks for it directly
      ...[400, 500, 600, 700, 800].map((w) => ['Plus Jakarta Sans', w, 'normal', '100%']),
    ];

    for (const [family, weight, style, scale] of faces) {
      for (const subset of ['latin', 'latinExt']) {
        const buffer = buffers[`${subset}-${style}`];
        try {
          const face = new FontFace(family, buffer, {
            weight: String(weight),
            style,
            unicodeRange: data.ranges[subset],
            display: 'swap',
            sizeAdjust: scale,
          });
          document.fonts.add(face);
        } catch (e) {
          console.warn('[UPC branding] font face not added', family, weight, style, e);
        }
      }
    }
  }

  // ---- Favicon --------------------------------------------------------------

  function setFavicon() {
    const links = document.querySelectorAll('link[rel~="icon"]');
    if (!links.length) {
      const link = document.createElement('link');
      link.rel = 'icon';
      link.href = FAVICON_URL;
      document.head.appendChild(link);
      return;
    }
    links.forEach((link) => {
      if (link.href !== FAVICON_URL) link.href = FAVICON_URL;
    });
  }

  function watchFavicon() {
    setFavicon();
    // Halaxy may swap the icon when it changes page; put ours back if it does.
    let queued = false;
    new MutationObserver(() => {
      if (queued) return;
      queued = true;
      requestAnimationFrame(() => { queued = false; setFavicon(); });
    }).observe(document.head, { childList: true, subtree: true, attributes: true, attributeFilter: ['href'] });
  }

  // ---- Embedded font files ------------------------------------------------------
  // Plus Jakarta Sans 5.3.0, variable woff2, weight axis limited to 500-800.
  // At Halaxy's small text sizes Regular and Light strokes render thinner than
  // a pixel, which makes text look faint and spidery (measured: grey labels
  // averaged #999 on screen instead of their #62626E). So anything Halaxy asks
  // for at 300 or 400 renders at Medium (500).

  function fontData() {
    return {
      ranges: {
        latin: 'U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD',
        latinExt: 'U+0100-02BA,U+02BD-02C5,U+02C7-02CC,U+02CE-02D7,U+02DD-02FF,U+0304,U+0308,U+0329,U+1D00-1DBF,U+1E00-1E9F,U+1EF2-1EFF,U+2020,U+20A0-20AB,U+20AD-20C0,U+2113,U+2C60-2C7F,U+A720-A7FF',
      },
      files: {
        'latin-normal': '',
        'latin-italic': '',
        'latinExt-normal': '',
        'latinExt-italic': '',
      },
    };
  }
})();
